style.css:
@-moz-document domain("roblox.com") {
html, body, #app {
    background: transparent !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;

    background-image: url("https://files.catbox.moe/x0kd5l.gif");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    z-index: -999999;
    pointer-events: none;
}
}
